  Summon_97987_ProbabilityUpDesc = {
    Text = "Unutuş Destanı <SummonBlue:Aequor> Sınırlı SSR'ler"
  },
  Summon_97987_RateListTextSSR = {
    Text = "SSR Eşya Garantili Kapsamlı Düşme Oranı: 100,00%"
